(function(){
  'use strict';
  const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let controller=null,state={phase:'loading',user:null,profile:null,error:''},initPromise=null,profileDirty=false,profileSaving=false,identity=null,sharedClient=null,queuedAndroidOAuthCallback=null;
  if(window.YamaConvertAndroid){queuedAndroidOAuthCallback=typeof window.__yamaconvertOAuthCallback==='string'?window.__yamaconvertOAuthCallback:null;delete window.__yamaconvertOAuthCallback;window.addEventListener('yamaconvert-oauth-callback',event=>{if(typeof event.detail!=='string')return;queuedAndroidOAuthCallback=event.detail;if(identity)void completeAndroidOAuth(event.detail);});}
  const signedIn=()=>!!state.user&&['signed-in','profile-error'].includes(state.phase);
  const name=()=>state.profile?.display_name||state.profile?.username||state.user?.email||'Yama účet';
  function providerBrand(provider){const keys={azure:'microsoft','custom:seznam':'seznam','custom:mojeid':'mojeid'};return keys[provider.id]||provider.id;}
  function providerIcon(provider){const brand=providerBrand(provider);if(brand==='seznam')return '<span class="provider-badge provider-letter" aria-hidden="true">S</span>';if(brand==='mojeid')return '<span class="provider-badge provider-letter provider-id" aria-hidden="true">ID</span>';return `<span class="provider-badge"><img class="provider-icon" src="assets/providers/${brand}.svg" alt="" width="24" height="24"></span>`;}
  function providerItems(mode,showPending=false){if(!identity)return '<p class="caption">Možnosti přihlášení právě připravujeme.</p>';const linked=new Set((state.user?.identities||[]).map(item=>item.provider));let items=identity.providers(mode);if(mode==='signin'&&!showPending){if(items.some(item=>item.reason==='callback')&&!items.some(item=>item.ready))return '<p class="caption">Pro tento testovací web ještě není povolen návrat z externího přihlášení. Zatím použij e-mail a heslo svého původního účtu Yamachat.</p>';items=items.filter(item=>item.ready);if(!items.length)return '<p class="caption">Google, Microsoft, Seznam a další možnosti přihlášení připravujeme. Zatím použij svůj e-mail a heslo.</p>';}return `<div class="provider-grid">${items.map(provider=>`<div class="provider-option brand-${providerBrand(provider)}"><div class="provider-head">${providerIcon(provider)}<strong>${escape(provider.name)}</strong></div>${(linked.has(provider.id)||linked.has(provider.id.replace(/^custom:/,'')))?'<span class="pill available">Propojené s tímto účtem</span>':provider.ready?`<button class="secondary" data-oauth-provider="${escape(provider.id)}" data-oauth-mode="${mode}">${mode==='link'?'Připojit':'Pokračovat'}</button>`:'<span class="provider-pending">'+escape(providerPending(provider))+'</span>'}</div>`).join('')}</div><p class="caption">Po prvním podporovaném přihlášení vznikne účet Yamaportal. Další služby přidávej k existujícímu účtu. Dostupnost přihlášení a propojení YamaSearch ověřujeme postupně.</p><p class="form-status" role="status" data-provider-status></p>`;}
  function providerPending(provider){return {unavailable:'Dostupnost se nepodařilo ověřit. Zkontroluj připojení.',setup:'Připravuje se',callback:'Pro toto prostředí se připravuje',linking:'Propojení účtu se připravuje'}[provider.reason]||'Připravuje se';}
  function registrationProviders(){const providers=(identity?.providers('signin')||[]).filter(provider=>provider.ready);if(!providers.length)return '<p class="caption">Přihlášení přes propojené služby se připravuje.</p>';return `<div class="registration-providers" aria-label="Přihlášení přes externí účet">${providers.map(provider=>`<button type="button" class="registration-provider brand-${providerBrand(provider)}" data-oauth-provider="${escape(provider.id)}" data-oauth-mode="signin" title="Pokračovat přes ${escape(provider.name)}" aria-label="Pokračovat přes ${escape(provider.name)}">${providerIcon(provider)}</button>`).join('')}</div><p class="form-status" role="status" data-provider-status></p>`;}
  function providerRegion(mode,showPending=false){return `<section class="provider-region"><h3>${mode==='link'?'Přihlášení k tvému účtu':'Další způsoby přihlášení'}</h3><button type="button" class="text-button" data-provider-refresh>Ověřit dostupné přihlášení</button><button type="button" class="secondary" data-oauth-cancel ${identity?.hasPending()?"":"hidden"}>Zrušit předchozí přihlášení</button><div data-provider-options="${mode}" data-show-pending="${showPending}">${providerItems(mode,showPending)}</div></section>`;}
  async function cancelOAuth(){identity?.cancel();await window.YamaNative?.oauth?.cancel();oauthNotice('Předchozí přihlášení bylo zrušeno. Můžeš začít znovu.');refreshProviders();}
  function refreshProviders(){document.querySelectorAll('[data-oauth-cancel]').forEach(button=>{button.hidden=!identity?.hasPending();});document.querySelectorAll('[data-provider-options]').forEach(region=>{region.innerHTML=providerItems(region.dataset.providerOptions,region.dataset.showPending==='true');});const registration=document.querySelector('[data-register-providers]');if(registration)registration.innerHTML=registrationProviders();}
  function oauthNotice(message){let notice=document.querySelector('#oauth-notice');if(!notice){notice=document.createElement('div');notice.id='oauth-notice';notice.className='notice oauth-notice';notice.setAttribute('role','status');document.querySelector('main').prepend(notice);}notice.textContent=message;}
  async function completeAndroidOAuth(url){if(!identity){queuedAndroidOAuthCallback=url;return;}if(queuedAndroidOAuthCallback===url)queuedAndroidOAuthCallback=null;try{await identity.finish(url);await controller.restore();location.hash='profil';oauthNotice('Přihlášení bylo ověřeno. Používáš svůj účet Yamaportal.');}catch(error){oauthNotice(error.message||'Přihlášení se nepodařilo dokončit.');}refreshProviders();}
  function configureIdentity(client,policy,boundedFetch,publishableKey){const native=window.YamaNative?.oauth,android=window.YamaConvertAndroid;const target=native?{href:location.href,assign:url=>native.begin(url,YamaIdentityCore.callbackFor(location,policy))}:location;const callbackUrl=android?YamaIdentityCore.ANDROID_CALLBACK:null;const instance=new YamaIdentityCore.IdentityController({client,policy,fetch:url=>boundedFetch(url,{headers:{apikey:publishableKey}}),storage:localStorage,location:target,callbackUrl});const complete=async url=>{try{await instance.finish(url);await controller.restore();location.hash='profil';oauthNotice('Přihlášení bylo ověřeno. Používáš svůj účet Yamaportal.');}catch(error){oauthNotice(error.message||'Přihlášení se nepodařilo dokončit.');}refreshProviders();};if(native)native.onCallback(complete);return instance;}
  function avatar(){const p=state.profile;let url='';if(p?.avatar_path)url=`${YamaAccountCore.AUTHORITY}/storage/v1/object/public/avatars/${p.avatar_path.split('/').map(encodeURIComponent).join('/')}`;
    if(p?.use_discord_avatar&&p.discord_avatar_url){try{const candidate=new URL(p.discord_avatar_url);if(candidate.protocol==='https:'&&['cdn.discordapp.com','media.discordapp.net'].includes(candidate.hostname))url=candidate.href;}catch{}}
    return url?`<img class="account-avatar" src="${escape(url)}" alt="Profilový obrázek">`:`<span class="account-avatar initials" aria-hidden="true">${escape(name().slice(0,1).toLocaleUpperCase('cs'))}</span>`;
  }
  function authForm(){return `<div class="account-auth"><h2>Přihlášení do Yamaportalu</h2><p class="muted">Už máš účet Yamachat? Nejdřív se přihlas původním e-mailem a heslem. Další přihlašovací službu k němu přidej v sekci Propojení; potom ho můžeš používat i na dalších zařízeních.</p>${providerRegion('signin')}<form id="portal-login"><label for="portal-email">E-mail</label><input id="portal-email" type="email" autocomplete="username" required maxlength="254"><label for="portal-password">Heslo</label><div class="password-row"><input id="portal-password" type="password" autocomplete="current-password" required><button type="button" id="toggle-password" aria-label="Zobrazit heslo">Zobrazit</button></div><button class="primary" type="submit">Přihlásit se</button><p class="form-status" role="status" id="login-status"></p></form><button class="text-button" data-account="recovery">Zapomenuté heslo</button><p class="caption">Relaci ukládá tento prohlížeč do odhlášení. Na sdíleném zařízení se po použití odhlas.</p><button class="text-button" data-account="register">Vytvořit nový účet Yamaportal</button><p class="caption">Google účet YamaSearch se s Yamachat účtem zatím nesloučí automaticky. Současné přihlášení YamaSearch zůstává funkční.</p></div>`;}
  function profilePage(){
    if(state.phase==='loading')return '<section class="panel page-content"><h2>Můj profil</h2><p role="status">Ověřuji přihlášení…</p></section>';
    if(!signedIn())return `<section class="panel page-content account-page">${state.error?`<p class="form-error" role="alert">${escape(state.error)}</p><button class="secondary" data-account="retry">Zkusit znovu</button>`:''}${authForm()}</section>`;
    return `<section class="panel page-content account-page"><div class="profile-heading">${avatar()}<div><h2>${escape(name())}</h2><p class="muted">${escape(state.user.email)}</p></div><span class="pill available">Yamaportal</span></div><p>Stejný profil jako v Yamachatu. Uložené změny se projeví také tam při dalším načtení profilu.</p>${state.profile?`<form id="portal-profile"><label for="profile-name">Zobrazované jméno</label><input id="profile-name" value="${escape(state.profile.display_name||state.profile.username)}" maxlength="80" required autocomplete="nickname"><label for="profile-bio">O mně</label><textarea id="profile-bio" maxlength="500" rows="4">${escape(state.profile.bio||'')}</textarea><p class="caption">Uživatelské jméno: ${escape(state.profile.username)}. Avatar je převzatý z tvého současného profilu.</p><button class="primary" type="submit">Uložit společný profil</button><p role="status" id="profile-status" class="form-status"></p></form>`:`<p role="alert">${escape(state.error)}</p><button class="secondary" data-account="retry">Načíst profil znovu</button>`}<div class="profile-actions"><button class="secondary" data-account="recovery">Obnovit heslo</button><button class="secondary" data-route="propojeni">Propojené aplikace</button><button class="secondary danger" data-account="logout">Odhlásit toto přihlášení</button></div><p class="caption">Odhlášení Portalu neruší ostatní samostatné relace Yamachatu nebo YamaSearch. Portál nezobrazuje seznam zařízení jako seznam aktivních přihlášení.</p><p id="account-action-status" role="status" class="form-status"></p></section>`;
  }
  function dashboardSummary(){
    const active=signedIn();
    let memberSince='';
    if(active&&state.user?.created_at){const created=new Date(state.user.created_at);if(Number.isFinite(created.getTime()))memberSince=new Intl.DateTimeFormat('cs-CZ',{month:'long',year:'numeric'}).format(created);}
    return Object.freeze({signedIn:active,name:active?name():'',email:active?String(state.user.email||''):'',avatar:active?avatar():'',memberSince,profileReady:!!state.profile,phase:state.phase});
  }
  function home(){return `<aside class="panel account">${signedIn()?`<div class="profile-heading">${avatar()}<div><h2>${escape(name())}</h2><p class="caption">${escape(state.user.email)}</p></div></div><div class="notice"><strong>Společný profil Yamachat a Yamaportal</strong>YamaSearch podporuje volitelné přihlášení tímto účtem ve Windows. Jeho původní účet i samostatný provoz zůstávají zachované.</div><button class="primary" data-route="profil">Spravovat profil</button><button class="secondary" data-route="propojeni">Propojené aplikace</button>`:`<img class="logo" src="assets/yamaportal.png" alt="Yamaportal"><h2>Tvůj účet Yamaportal</h2><p class="muted">Stávající účet Yamachat<br>pro společný Yamaportal.</p><div class="notice"><strong>Bez nové registrace</strong>Přihlas se svým účtem Yamachat. Profily, přátelé, komunity a zprávy zůstávají zachované.</div><button class="primary" data-route="profil">${state.phase==='loading'?'Ověřuji přihlášení…':'Přihlásit se'}</button><button class="secondary" data-account="recovery">Zapomenuté heslo</button>`}<p class="caption">YamaHelp funguje samostatně bez povinného účtu. Žádná data aplikací se automaticky neslučují.</p></aside>`;}
  function connections(){return `<section class="panel page-content"><h2>Propojení a synchronizace</h2><p class="muted">Společná identita a data aplikací mají rozdílný rozsah.</p>${providerRegion(signedIn()?'link':'signin',true)}<div class="rows"><article class="row"><h3>Yamachat ↔ Yamaportal</h3><span class="pill ${signedIn()?'available':''}">${signedIn()?'Stejný účet a profil':'Připravené přihlášení'}</span><p>Portal čte a upravuje tentýž profil. Heslo se obnovuje stávajícím e-mailem Yamachatu.</p></article><article class="row"><h3>YamaSearch</h3><span class="pill">Společné přihlášení podporuje Windows 0.3.22</span><p>Windows verze umí volitelně použít centrální účet Yamaportal a načíst jeho profil. Původní účet YamaSearch zůstává zachovaný a lze jej dál zvolit.</p><p>Společný účet zatím není součástí Android verze ani iOS startovní PWA. Záložky, historie a otevřené karty se mezi účty neslučují ani nesynchronizují.</p></article><article class="row"><h3>YamaHelp</h3><p>Základní funkce pro Windows zůstávají bez povinného účtu.</p></article><article class="row"><h3>YamaMaker a YamaView</h3><p>Připravuje se. Zatím nemají ověřené společné přihlášení.</p></article></div></section>`;}
  function recovery(){const dialog=document.querySelector('#account-dialog');dialog.innerHTML=`<button class="close" data-account="close" aria-label="Zavřít">×</button><h2>Obnova hesla Yamaportal</h2><p>Použijeme stejnou obnovu jako Yamachat. E-mail může zatím nést název Yamachat; odkaz nastaví heslo ke stejnému účtu v Portalu i Yamachatu.</p><form id="portal-recovery"><label for="recovery-email">E-mail účtu</label><input id="recovery-email" type="email" autocomplete="email" value="${escape(state.user?.email||'')}" required><button class="primary" type="submit">Odeslat odkaz pro obnovu</button><p id="recovery-status" class="form-status" role="status"></p></form><p class="caption">Heslo k samostatnému YamaSearch účtu tím zatím neměníš. Přihlášení přes Google používá zabezpečení účtu Google.</p>`;dialog.showModal();dialog.querySelector('#recovery-email').focus();}
  function header(){const el=document.querySelector('#account-menu-button');if(!el)return;el.innerHTML=signedIn()?`${avatar()}<span>${escape(name())}</span>`:'<span aria-hidden="true">◉</span><span>Můj účet</span>';el.setAttribute('aria-label',signedIn()?`Účet ${name()}`:'Přihlásit se k účtu Yamaportal');}
  function registration(){const dialog=document.querySelector('#account-dialog');dialog.innerHTML=`<button class="close" data-account="close" aria-label="Zavřít">×</button><h2>Nový účet Yamaportal</h2><p>Už máš Yamachat účet? Použij přihlášení nebo obnovu hesla. Novou registraci nepotřebuješ.</p><form id="portal-register"><label for="register-name">Uživatelské jméno</label><input id="register-name" autocomplete="username" required minlength="3" maxlength="32" pattern="[a-zA-Z0-9_.-]{3,32}"><label for="register-email">E-mail</label><input id="register-email" type="email" autocomplete="email" required maxlength="254"><label for="register-password">Heslo</label><input id="register-password" type="password" autocomplete="new-password" required minlength="8"><label for="register-confirm">Heslo znovu</label><input id="register-confirm" type="password" autocomplete="new-password" required minlength="8"><p class="caption">Registrace používá skutečný společný účet Yamachat/Yamaportal. <a href="privacy.html" target="_blank" rel="noopener noreferrer">Soukromí a společný účet</a></p><button class="primary" type="submit">Vytvořit účet</button><p id="register-status" class="form-status" role="status"></p><div class="registration-auth"><span>Pokračovat přes připojený účet</span><div data-register-providers>${registrationProviders()}</div></div></form>`;dialog.showModal();dialog.querySelector('#register-name').focus();}
  function menu(){if(!signedIn()){location.hash='profil';return;}const dialog=document.querySelector('#account-dialog');if(dialog.open){dialog.close();return;}dialog.classList.add('account-menu-dialog');dialog.innerHTML=`<button class="close" data-account="close" aria-label="Zavřít">×</button><div class="profile-heading">${avatar()}<div><h2>${escape(name())}</h2><p class="caption">${escape(state.user.email)}</p></div></div><div class="account-menu-actions"><button class="secondary" data-account="profile">♙ &nbsp; Můj profil</button><button class="secondary" data-account="account-settings">⚙ &nbsp; Nastavení účtu</button><button class="secondary" data-account="connections">⇄ &nbsp; Propojené aplikace</button>${window.YamaAdminUI?.isAdmin()?'<button class="secondary owner-entry" data-account="admin">⚙ &nbsp; Správa Yamaportalu</button>':''}<button class="secondary danger" data-account="logout">↪ &nbsp; Odhlásit se</button></div><p id="account-action-status" class="form-status" role="status">Odhlášení Portalu neukončí samostatné relace ostatních aplikací.</p>`;dialog.showModal();}
  async function init(){if(initPromise)return initPromise;initPromise=(async()=>{try{
    const response=await fetch('./account-config.json',{cache:'no-store'});if(!response.ok)throw new Error('Konfigurace účtu není dostupná.');const config=YamaAccountCore.validateConfig(await response.json());
    if(!window.supabase?.createClient)throw new Error('Knihovna účtu se nepodařila načíst.');
    const boundedFetch=async(url,options={})=>{const abort=new AbortController();const forward=()=>abort.abort();if(options.signal?.aborted)abort.abort();else options.signal?.addEventListener('abort',forward,{once:true});const timer=setTimeout(()=>abort.abort(),25000);try{return await fetch(url,{...options,signal:abort.signal});}finally{clearTimeout(timer);options.signal?.removeEventListener('abort',forward);}};
    const client=window.supabase.createClient(config.authorityUrl,config.publishableKey,{auth:{storageKey:'yamaportal-auth-v1',persistSession:true,autoRefreshToken:true,detectSessionInUrl:false,flowType:'pkce',...(window.YamaNative?.storage?{storage:window.YamaNative.storage}:{})},global:{fetch:boundedFetch,headers:{'X-Client-Info':'yamaportal-local-account/0.1'}}});
    sharedClient=client; let recoveryClient=null;const recoveryAuth={resetPasswordForEmail(email,options){if(!recoveryClient)recoveryClient=window.supabase.createClient(config.authorityUrl,config.publishableKey,{auth:{storageKey:'yamaportal-recovery-request-v1',persistSession:false,autoRefreshToken:false,detectSessionInUrl:false,flowType:'implicit'},global:{fetch:boundedFetch}});return recoveryClient.auth.resetPasswordForEmail(email,options);}};
    controller=new YamaAccountCore.AccountController(client,config,{recoveryAuth});controller.subscribe(next=>{if(state.user&&next.user?.id!==state.user.id){const dialog=document.querySelector('#account-dialog');if(dialog?.open)dialog.close();if(dialog)dialog.innerHTML='';}if(next.user?.id!==state.user?.id||!['signed-in','profile-error'].includes(next.phase))profileDirty=false;state=next;header();document.dispatchEvent(new CustomEvent('yama-account-state'));refreshProviders();});await controller.start();
    if(typeof YamaIdentityCore!=='undefined'){try{const response=await boundedFetch('./identity-providers.json',{cache:'no-store'});if(response.ok){const policy=await response.json();identity=configureIdentity(client,policy,boundedFetch,config.publishableKey);await identity.discover();if(queuedAndroidOAuthCallback)await completeAndroidOAuth(queuedAndroidOAuthCallback);refreshProviders();}}catch{/* Password sign-in remains independent of provider discovery. */}}
  }catch{state={phase:'error',user:null,profile:null,error:'Účet se nepodařilo připravit. Zkontroluj připojení a obnov stránku.'};header();document.dispatchEvent(new CustomEvent('yama-account-state'));}})();return initPromise;}
  async function submit(form,statusId,operation,success){const status=form.querySelector(statusId);const button=form.querySelector('[type=submit]');const savingProfile=form.id==='portal-profile';if(savingProfile)profileSaving=true;button.disabled=true;status.textContent='Pracuji…';status.classList.remove('form-error');try{if(!controller)throw new Error('Přihlášení není připravené. Obnov stránku a zkus to znovu.');const result=await operation();if(savingProfile&&result!==false)profileDirty=false;status.textContent=result===false?'Relace se mezitím změnila.':typeof result==='string'?result:success;}catch(error){status.textContent=error.message;status.classList.add('form-error');}finally{if(savingProfile)profileSaving=false;button.disabled=false;}}
  document.addEventListener('submit',event=>{const form=event.target;if(!['portal-login','portal-profile','portal-recovery','portal-register'].includes(form.id))return;event.preventDefault();if(!form.reportValidity())return;
    if(form.id==='portal-login'){const email=form.querySelector('#portal-email').value,password=form.querySelector('#portal-password').value;form.querySelector('#portal-password').value='';void submit(form,'#login-status',()=>controller.signIn(email,password),'Přihlášeno.');}
    if(form.id==='portal-register'){const values={email:form.querySelector('#register-email').value,username:form.querySelector('#register-name').value,password:form.querySelector('#register-password').value,confirmation:form.querySelector('#register-confirm').value};form.querySelector('#register-password').value='';form.querySelector('#register-confirm').value='';void submit(form,'#register-status',()=>controller.signUp(values),'Žádost přijata.');}
    if(form.id==='portal-profile')void submit(form,'#profile-status',()=>controller.saveProfile({display_name:form.querySelector('#profile-name').value,bio:form.querySelector('#profile-bio').value}),'Společný profil byl uložen.');
    if(form.id==='portal-recovery')void submit(form,'#recovery-status',()=>controller.requestRecovery(form.querySelector('#recovery-email').value),'Žádost byla přijata.');
  });
  document.addEventListener('click',async event=>{const toggle=event.target.closest('#toggle-password');if(toggle){const input=document.querySelector('#portal-password');input.type=input.type==='password'?'text':'password';toggle.textContent=input.type==='password'?'Zobrazit':'Skrýt';toggle.setAttribute('aria-label',input.type==='password'?'Zobrazit heslo':'Skrýt heslo');return;}
    const cancelOAuthButton=event.target.closest('[data-oauth-cancel]');if(cancelOAuthButton){await cancelOAuth();return;}
    const refresh=event.target.closest('[data-provider-refresh]');if(refresh){refresh.disabled=true;try{await identity?.discover();refreshProviders();}finally{refresh.disabled=false;}return;}
    const oauth=event.target.closest('[data-oauth-provider]');if(oauth){const region=oauth.closest('[data-provider-options]');const status=region?.querySelector('[data-provider-status]')||oauth.closest('#account-dialog')?.querySelector('[data-provider-status]');oauth.disabled=true;try{if(!identity)throw new Error('Přihlášení přes poskytovatele se ještě připravuje.');await identity.begin(oauth.dataset.oauthProvider,oauth.dataset.oauthMode);if(window.YamaNative?.oauth){oauthNotice("Dokonči přihlášení v systémovém prohlížeči. Místní aplikace můžeš dál používat.");const cancel=document.createElement("button");cancel.className="secondary";cancel.textContent="Zrušit přihlášení";cancel.onclick=()=>{identity.cancel();void window.YamaNative.oauth.cancel();oauthNotice("Přihlášení bylo zrušeno.");};document.querySelector("#oauth-notice").append(cancel);}else if(window.YamaConvertAndroid){oauthNotice('Dokonči přihlášení v prohlížeči. Po ověření se automaticky vrátíš do aplikace.');}}catch(error){if(status)status.textContent=error.message;else oauthNotice(error.message);}finally{oauth.disabled=false;document.querySelectorAll('[data-oauth-cancel]').forEach(button=>{button.hidden=!identity?.hasPending();});}return;}
    const action=event.target.closest('[data-account]')?.dataset.account;if(!action)return;
    if(action==='register')registration();if(action==='recovery')recovery();if(action==='menu')menu();if(action==='close'){if(identity?.hasPending()||identity?.busy)await cancelOAuth();document.querySelector('#account-dialog').close();}
    if(action==='profile'||action==='account-settings'||action==='connections'||action==='admin'){document.querySelector('#account-dialog').close();location.hash=action==='connections'?'propojeni':action==='admin'?'sprava':'profil';}
    if(action==='retry'){if(controller)await controller.restore();else location.reload();}
    if(action==='logout'){const button=event.target.closest('button');button.disabled=true;try{if(!controller)throw new Error('Účet není připravený.');identity?.cancel();await window.YamaNative?.oauth?.cancel();await window.YamaModuleHost?.prepareLogout();await controller.signOut();document.querySelector('#account-dialog').close();}catch(error){const status=document.querySelector('#account-dialog[open] #account-action-status')||document.querySelector('#page #account-action-status');if(status)status.textContent=error.message;}finally{button.disabled=false;}}
  });
  document.addEventListener('input',event=>{if(event.target.closest('#portal-profile'))profileDirty=true;});
  window.YamaPortalIntegration=Object.freeze({sharedClient(origin){if(origin!==location.origin||!sharedClient)throw new Error('Společný účet není připravený.');return sharedClient;},async requestRecovery(email){if(!controller)throw new Error('Účet není připravený.');await controller.requestRecovery(email);return {data:{},error:null};}});
  window.addEventListener('pageshow',()=>refreshProviders());
  window.addEventListener('focus',()=>refreshProviders());
  document.querySelector('#account-dialog')?.addEventListener?.('cancel',()=>{if(identity?.hasPending()||identity?.busy)void cancelOAuth();});
  document.querySelector('#account-dialog')?.addEventListener?.('close',event=>event.currentTarget.classList.remove('account-menu-dialog'));
  document.querySelector('#account-dialog')?.addEventListener?.('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close();});
  window.YamaAccountUI={isSignedIn:signedIn,init,home,dashboardSummary,profilePage,connections,shouldRender:()=>!signedIn()||(!profileDirty&&!profileSaving),clearDirty:()=>{profileDirty=false;}};
})();






